const body = $input.first().json.body;
const required = ['vendor_name', 'category', 'use_case', 'evaluation_criteria'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (!Array.isArray(body.evaluation_criteria) || body.evaluation_criteria.length < 2) {
  return [{ json: { valid: false, error: 'evaluation_criteria must be an array with at least 2 items' } }];
}
const criteria = body.evaluation_criteria.map(c => ({
  name: (typeof c === 'string') ? c : c.name,
  weight: (typeof c === 'object' && c.weight) ? parseFloat(c.weight) : 1,
  score: (typeof c === 'object' && c.score !== undefined) ? parseFloat(c.score) : null,
  notes: (typeof c === 'object' && c.notes) ? c.notes : ''
}));
const totalWeight = criteria.reduce((s,c) => s + c.weight, 0);
criteria.forEach(c => c.normalizedWeight = parseFloat((c.weight / totalWeight * 100).toFixed(1)));
const scoredCriteria = criteria.filter(c => c.score !== null);
let weightedScore = null;
if (scoredCriteria.length === criteria.length) {
  weightedScore = parseFloat(criteria.reduce((s,c) => s + (c.score * c.normalizedWeight / 100), 0).toFixed(1));
}
return [{ json: {
  valid: true,
  vendorName: body.vendor_name.trim(),
  vendorUrl: body.vendor_url || '',
  category: body.category.trim(),
  useCase: body.use_case.trim().slice(0, 600),
  evaluationCriteria: criteria,
  weightedScore,
  budget: body.budget || '',
  currency: body.currency || 'USD',
  alternatives: Array.isArray(body.alternatives) ? body.alternatives.slice(0, 4) : (body.alternatives || '').split(',').map(a=>a.trim()).filter(Boolean).slice(0,4),
  teamSize: body.team_size || '',
  integrationRequirements: (body.integration_requirements || '').slice(0, 400),
  securityRequirements: (body.security_requirements || '').slice(0, 300),
  additionalContext: (body.additional_context || '').slice(0, 500),
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

const vendorSearch = $('Research Vendor').first().json?.results || [];
const altSearch = $('Research Alternatives').first().json?.results || [];
const input = $('Validate Input').first().json;
const vendorContext = vendorSearch.map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,350)}`).join('\n\n');
const altContext = altSearch.map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,300)}`).join('\n\n');
return [{ json: { input, vendorContext, altContext } }];

values.content:
Evaluate this vendor for the described use case.

Vendor: {{ $json.input.vendorName }}{{ $json.input.vendorUrl ? ' (' + $json.input.vendorUrl + ')' : '' }}
Category: {{ $json.input.category }}
Use case: {{ $json.input.useCase }}
Budget: {{ $json.input.budget || 'not specified' }}
Team size: {{ $json.input.teamSize || 'not specified' }}
Alternatives being considered: {{ $json.input.alternatives.join(', ') || 'none specified' }}
Integration requirements: {{ $json.input.integrationRequirements || 'none specified' }}
Security requirements: {{ $json.input.securityRequirements || 'none specified' }}
Additional context: {{ $json.input.additionalContext || 'none' }}

Evaluation criteria with weights:
{{ $json.input.evaluationCriteria.map(c => `- ${c.name} (weight: ${c.normalizedWeight}%): ${c.score !== null ? 'pre-scored ' + c.score + '/10' : 'needs scoring'}${c.notes ? ' — ' + c.notes : ''}`).join('\n') }}

Current weighted score (if all criteria scored): {{ $json.input.weightedScore || 'not all criteria scored yet' }}

Vendor research:
{{ $json.vendorContext }}

Alternatives comparison research:
{{ $json.altContext }}

Return this JSON:
{
  "overall_verdict": "one of: strong_fit | good_fit | acceptable | poor_fit | not_recommended",
  "confidence": "high | medium | low",
  "executive_summary": "3-4 sentences — what this vendor is, how it fits the use case, and the bottom-line recommendation",
  "criteria_assessments": [
    {
      "criterion": "criterion name",
      "score_suggestion": 7.5,
      "evidence": "specific evidence from research supporting this score",
      "use_case_relevance": "how this criterion applies specifically to their use case"
    }
  ],
  "strengths": ["specific strengths relevant to this use case — not generic praise"],
  "weaknesses": ["specific weaknesses — honest about gaps"],
  "red_flags": ["anything that should give serious pause — empty if none"],
  "vs_alternatives": [
    {
      "alternative": "competitor name",
      "comparison": "1-2 sentences on key difference and when to choose this vendor vs that alternative"
    }
  ],
  "implementation_considerations": "what getting started actually looks like — onboarding, migration, typical timeline",
  "cost_assessment": "honest assessment of total cost including setup, training, potential overages — not just license price",
  "questions_for_vendor": ["4-6 specific questions to ask in a demo or sales call — based on the evaluation gaps"],
  "suggested_poc_criteria": ["3-4 specific things to test in a proof of concept or trial — concrete, not vague"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let evaluation;
try { evaluation = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
evaluation._meta = { vendorName: input.vendorName, category: input.category, useCase: input.useCase, weightedScore: input.weightedScore, currency: input.currency, replyEmail: input.replyEmail };
return [{ json: evaluation }];

const e = $input.first().json;
const m = e._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const verdictConfig = {
  strong_fit:        {color:'#16a34a', bg:'#f0fdf4', label:'Strong Fit ✓'},
  good_fit:          {color:'#2563eb', bg:'#eff6ff', label:'Good Fit'},
  acceptable:        {color:'#d97706', bg:'#fffbeb', label:'Acceptable'},
  poor_fit:          {color:'#ea580c', bg:'#fff7ed', label:'Poor Fit'},
  not_recommended:   {color:'#dc2626', bg:'#fef2f2', label:'Not Recommended ✗'}
};
const vc = verdictConfig[e.overall_verdict] || verdictConfig.acceptable;
const confColor = {high:'#16a34a', medium:'#d97706', low:'#dc2626'};

const criteriaRows = (e.criteria_assessments||[]).map(c => {
  const score = c.score_suggestion;
  const barWidth = Math.round((score||0) / 10 * 100);
  return `<div style="padding:10px 0;border-bottom:1px solid #f3f4f6">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
      <span style="font-size:14px;font-weight:600">${esc(c.criterion)}</span>
      <span style="font-size:15px;font-weight:700;color:${score>=7?'#16a34a':score>=5?'#d97706':'#dc2626'}">${score||'?'}/10</span>
    </div>
    <div style="background:#f3f4f6;border-radius:4px;height:6px;margin-bottom:6px"><div style="background:${score>=7?'#16a34a':score>=5?'#d97706':'#dc2626'};height:6px;border-radius:4px;width:${barWidth}%"></div></div>
    <div style="font-size:12px;color:#6b7280;line-height:1.5">${esc(c.evidence)}</div>
  </div>`;
}).join('');

const strengths = (e.strengths||[]).map(s => `<div style="font-size:14px;padding:6px 0;border-bottom:1px solid #f0fdf4;color:#166534">+ ${esc(s)}</div>`).join('');
const weaknesses = (e.weaknesses||[]).map(w => `<div style="font-size:14px;padding:6px 0;border-bottom:1px solid #fef9c3;color:#78350f">− ${esc(w)}</div>`).join('');
const redFlags = (e.red_flags||[]).map(f => `<div style="font-size:14px;padding:5px 0;color:#7f1d1d">⚠ ${esc(f)}</div>`).join('');
const vsAlts = (e.vs_alternatives||[]).map(a => `<div style="padding:9px 0;border-bottom:1px solid #f3f4f6"><div style="font-size:14px;font-weight:600">${esc(a.alternative)}</div><div style="font-size:13px;color:#555;margin-top:3px">${esc(a.comparison)}</div></div>`).join('');
const questions = (e.questions_for_vendor||[]).map((q,i) => `<div style="font-size:14px;padding:6px 0;border-bottom:1px solid #f0f9ff;color:#1e40af">${i+1}. ${esc(q)}</div>`).join('');
const pocItems = (e.suggested_poc_criteria||[]).map(p => `<li style="font-size:14px;margin-bottom:7px;line-height:1.5">${esc(p)}</li>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:700px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:5px">Vendor Evaluation · ${esc(m.category)}</div>
    <div style="font-size:20px;font-weight:700">${esc(m.vendorName)}</div>
    <div style="font-size:13px;color:#9ca3af;margin-top:3px">${esc(m.useCase.slice(0,100))}${m.useCase.length>100?'...':''}</div>
  </div>
  <div style="background:${vc.bg};padding:14px 28px;border:1px solid ${vc.color}44;border-top:none;display:flex;align-items:center;justify-content:space-between">
    <div>
      <span style="background:${vc.color};color:#fff;font-size:13px;font-weight:700;padding:4px 14px;border-radius:14px">${vc.label}</span>
      <span style="font-size:12px;color:${confColor[e.confidence]||'#6b7280'};margin-left:10px">${esc(e.confidence)} confidence</span>
    </div>
    ${m.weightedScore ? `<div style="text-align:right"><div style="font-size:11px;color:#9ca3af">Weighted score</div><div style="font-size:24px;font-weight:800">${m.weightedScore}/10</div></div>` : ''}
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:none">
    <p style="font-size:15px;line-height:1.75;color:#374151;margin:0">${esc(e.executive_summary)}</p>
  </div>
  ${criteriaRows ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Criteria scores</div>
    ${criteriaRows}
  </div>` : ''}
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">
      ${strengths ? `<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:7px">Strengths</div>${strengths}</div>` : ''}
      ${weaknesses ? `<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:7px">Weaknesses</div>${weaknesses}</div>` : ''}
    </div>
  </div>
  ${redFlags ? `<div style="background:#fef2f2;padding:14px 28px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:7px">Red flags</div>
    ${redFlags}
  </div>` : ''}
  ${vsAlts ? `<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">vs. alternatives</div>
    ${vsAlts}
  </div>` : ''}
  <div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Implementation & cost</div>
    <div style="font-size:14px;color:#374151;line-height:1.65;margin-bottom:8px">${esc(e.implementation_considerations)}</div>
    <div style="font-size:14px;color:#374151;line-height:1.65">${esc(e.cost_assessment)}</div>
  </div>
  ${questions ? `<div style="background:#eff6ff;padding:14px 28px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:7px">Ask in the demo</div>
    ${questions}
  </div>` : ''}
  ${pocItems ? `<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:7px">What to test in POC</div>
    <ul style="padding-left:18px;margin:0">${pocItems}</ul>
  </div>` : ''}
  <div style="background:#111827;color:#4b5563;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Vendor Evaluator · ${esc(m.vendorName)} · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, vendorName: m.vendorName, verdict: e.overall_verdict, weightedScore: m.weightedScore, evaluation: e } }];
